1	import { Flag, CheckCircle2, Clock } from "lucide-react";
2	import { PageHeader } from "@/components/shared/PageHeader";
3	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
4	import { Badge } from "@/components/ui/badge";
5	import { Switch } from "@/components/ui/switch";
6	import { Label } from "@/components/ui/label";
7	import { Skeleton } from "@/components/ui/skeleton";
8	import { format } from "date-fns";
9	import {
10	  FLAG_DEFINITIONS,
11	  useFeatureFlags,
12	  useUpdateFeatureFlag,
13	  type FlagDefinition,
14	} from "@/hooks/admin/use-feature-flags";
15	import { toast } from "sonner";
16	
17	// ── Constants ─────────────────────────────────────────────────
18	
19	const CATEGORY_LABELS: Record<FlagDefinition["category"], string> = {
20	  ui: "UI",
21	  feature: "Feature",
22	  system: "System",
23	};
24	
25	const CATEGORY_BADGE_CLASSES: Record<FlagDefinition["category"], string> = {
26	  ui: "bg-sky-100 text-sky-700 border-0",
27	  feature: "bg-indigo-100 text-indigo-700 border-0",
28	  system: "bg-red-100 text-red-700 border-0",
29	};
30	
31	// ── Skeleton ──────────────────────────────────────────────────
32	
33	function FlagsSkeleton() {
34	  return (
35	    <div className="space-y-8">
36	      {Array.from({ length: 3 }).map((_, i) => (
37	        <Card key={i} className="border-border/50 shadow-soft">
38	          <CardHeader className="pb-3">
39	            <Skeleton className="h-5 w-32" />
40	          </CardHeader>
41	          <CardContent className="divide-y divide-slate-100">
42	            {Array.from({ length: 2 }).map((__, j) => (
43	              <div key={j} className="flex items-start gap-4 py-4">
44	                <Skeleton className="h-5 w-9 rounded-full mt-0.5" />
45	                <div className="flex-1 space-y-2">
46	                  <Skeleton className="h-4 w-40" />
47	                  <Skeleton className="h-3 w-72" />
48	                </div>
49	                <Skeleton className="h-5 w-8 rounded-full mt-0.5" />
50	              </div>
51	            ))}
52	          </CardContent>
53	        </Card>
54	      ))}
55	    </div>
56	  );
57	}
58	
59	// ── Main page ─────────────────────────────────────────────────
60	
61	export default function AdminFeatureFlags() {
62	  const flagsQuery = useFeatureFlags();
63	  const updateFlag = useUpdateFeatureFlag();
64	
65	  const flags = flagsQuery.data?.flags ?? {};
66	  const updatedAt = flagsQuery.data?.updatedAt ?? null;
67	
68	  const handleToggle = (flag: FlagDefinition, enabled: boolean) => {
69	    if (updateFlag.isPending) return;
70	    updateFlag.mutate(
71	      {
72	        key: flag.key,
73	        enabled,
74	        currentFlags: flags,
75	      },
76	      {
77	        onError: () => {
78	          // Optimistic revert is handled by React Query re-fetching on error
79	          toast.error(`Failed to toggle ${flag.label}. Please try again.`);
80	        },
81	      }
82	    );
83	  };
84	
85	  const categories: FlagDefinition["category"][] = ["ui", "feature", "system"];
86	
87	  return (
88	    <div className="space-y-8">
89	      <PageHeader
90	        title="Feature Flags"
91	        description="Toggle features on/off across the platform. Changes take effect immediately for all users."
92	      />
93	
94	      {/* DB-backed success banner */}
95	      <div
96	        role="status"
97	        className="flex items-start gap-3 rounded-xl border border-green-200 bg-green-50 px-4 py-3.5"
98	      >
99	        <CheckCircle2 className="h-4 w-4 text-green-500 mt-0.5 shrink-0" />
100	        <div className="flex-1">
101	          <p className="text-sm font-medium text-green-800">
102	            Flags stored in database
103	          </p>
104	          <p className="text-xs text-green-700 mt-0.5">
105	            Feature flags are stored in{" "}
106	            <code className="font-mono text-xs bg-green-100 px-1 py-0.5 rounded">
107	              system_config
108	            </code>{" "}
109	            and apply platform-wide immediately.
110	            {updatedAt && (
111	              <span className="ml-1">
112	                Last updated{" "}
113	                {format(new Date(updatedAt), "MMM d, yyyy 'at' h:mm a")}.
114	              </span>
115	            )}
116	          </p>
117	        </div>
118	      </div>
119	
120	      {/* Loading state */}
121	      {flagsQuery.isLoading ? (
122	        <FlagsSkeleton />
123	      ) : flagsQuery.isError ? (
124	        <div
125	          role="alert"
126	          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
127	        >
128	          Failed to load feature flags. Check your admin permissions.
129	        </div>
130	      ) : (
131	        /* Flags by category */
132	        categories.map((category) => {
133	          const categoryFlags = FLAG_DEFINITIONS.filter(
134	            (f) => f.category === category
135	          );
136	
137	          return (
138	            <Card key={category} className="border-border/50 shadow-soft">
139	              <CardHeader className="pb-3">
140	                <div className="flex items-center gap-2">
141	                  <Flag className="h-4 w-4 text-muted-foreground" />
142	                  <CardTitle className="text-base font-semibold capitalize">
143	                    {category === "ui"
144	                      ? "UI Visibility"
145	                      : category === "feature"
146	                      ? "Feature Toggles"
147	                      : "System Flags"}
148	                  </CardTitle>
149	                </div>
150	              </CardHeader>
151	              <CardContent className="divide-y divide-slate-100">
152	                {categoryFlags.map((flag) => {
153	                  const enabled = flags[flag.key] ?? flag.defaultValue;
154	                  const isPending = updateFlag.isPending && updateFlag.variables?.key === flag.key;
155	
156	                  return (
157	                    <div
158	                      key={flag.key}
159	                      className="flex items-start gap-4 py-4 first:pt-0 last:pb-0"
160	                    >
161	                      {/* Toggle */}
162	                      <div className="pt-0.5">
163	                        <Switch
164	                          id={flag.key}
165	                          checked={enabled}
166	                          onCheckedChange={(v) => handleToggle(flag, v)}
167	                          disabled={isPending || updateFlag.isPending}
168	                          aria-label={`Toggle ${flag.label}`}
169	                        />
170	                      </div>
171	
172	                      {/* Info */}
173	                      <div className="flex-1 min-w-0">
174	                        <div className="flex items-center gap-2 flex-wrap">
175	                          <Label
176	                            htmlFor={flag.key}
177	                            className="text-sm font-medium cursor-pointer"
178	                          >
179	                            {flag.label}
180	                          </Label>
181	                          <Badge
182	                            className={`text-2xs px-1.5 py-0 ${
183	                              CATEGORY_BADGE_CLASSES[flag.category]
184	                            }`}
185	                          >
186	                            {CATEGORY_LABELS[flag.category]}
187	                          </Badge>
188	                          {flag.requiresSuperAdmin && (
189	                            <Badge className="bg-red-50 text-red-600 border-red-200 text-2xs px-1.5 py-0">
190	                              Super Admin
191	                            </Badge>
192	                          )}
193	                        </div>
194	                        <p className="mt-1 text-xs text-muted-foreground leading-relaxed">
195	                          {flag.description}
196	                        </p>
197	                        {updatedAt && (
198	                          <div className="mt-1.5 flex items-center gap-1 text-2xs text-muted-foreground/60">
199	                            <Clock className="h-2.5 w-2.5" />
200	                            <span>
201	                              Last changed{" "}
202	                              {format(
203	                                new Date(updatedAt),
204	                                "MMM d, yyyy 'at' h:mm a"
205	                              )}
206	                            </span>
207	                          </div>
208	                        )}
209	                      </div>
210	
211	                      {/* Status pill */}
212	                      <div className="shrink-0 pt-0.5">
213	                        {isPending ? (
214	                          <Badge className="bg-muted/50 text-slate-500 border-0 text-xs animate-pulse">
215	                            Saving…
216	                          </Badge>
217	                        ) : (
218	                          <Badge
219	                            className={
220	                              enabled
221	                                ? "bg-green-100 text-green-700 border-0 text-xs"
222	                                : "bg-muted/50 text-slate-500 border-0 text-xs"
223	                            }
224	                          >
225	                            {enabled ? "On" : "Off"}
226	                          </Badge>
227	                        )}
228	                      </div>
229	                    </div>
230	                  );
231	                })}
232	              </CardContent>
233	            </Card>
234	          );
235	        })
236	      )}
237	    </div>
238	  );
239	}
240

1	import { lazy, Suspense } from "react";
2	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
3	import { ThemeProvider } from "next-themes";
4	import { BrowserRouter, Route, Routes } from "react-router-dom";
5	import { Toaster as Sonner } from "@/components/ui/sonner";
6	import { Toaster } from "@/components/ui/toaster";
7	import { TooltipProvider } from "@/components/ui/tooltip";
8	import { AuthProvider } from "@/contexts/AuthContext";
9	import { ProtectedRoute } from "@/components/ProtectedRoute";
10	import { AdminRoute } from "@/components/AdminRoute";
11	import { AppLayout } from "@/components/AppLayout";
12	import Dashboard from "@/pages/Dashboard";
13	import Scan from "@/pages/Scan";
14	import Reports from "@/pages/Reports";
15	import AuditReport from "@/pages/AuditReport";
16	import Integrations from "@/pages/Integrations";
17	import SettingsPage from "@/pages/Settings";
18	import Pricing from "@/pages/Pricing";
19	import Landing from "@/pages/Landing";
20	import Login from "@/pages/Login";
21	import Signup from "@/pages/Signup";
22	import AuthCallback from "@/pages/AuthCallback";
23	import ForgotPassword from "@/pages/ForgotPassword";
24	import ResetPassword from "@/pages/ResetPassword";
25	import Privacy from "@/pages/Privacy";
26	import Terms from "@/pages/Terms";
27	import NotFound from "@/pages/NotFound";
28	
29	// ── Admin routes (lazy loaded) ────────────────────────────────
30	const AdminLayout = lazy(() =>
31	  import("@/components/AdminLayout").then((m) => ({ default: m.AdminLayout }))
32	);
33	const AdminDashboard = lazy(() => import("@/pages/admin/AdminDashboard"));
34	const AdminUsers = lazy(() => import("@/pages/admin/Users"));
35	const AdminUserDetail = lazy(() => import("@/pages/admin/UserDetail"));
36	const AdminAuditLog = lazy(() => import("@/pages/admin/AuditLog"));
37	const AdminScans = lazy(() => import("@/pages/admin/Scans"));
38	const AdminBilling = lazy(() => import("@/pages/admin/Billing"));
39	const AdminSystem = lazy(() => import("@/pages/admin/System"));
40	const AdminFeatureFlags = lazy(() => import("@/pages/admin/FeatureFlags"));
41	const AdminSupport = lazy(() => import("@/pages/admin/Support"));
42	
43	function AdminLoadingSpinner() {
44	  return (
45	    <div className="flex min-h-screen items-center justify-center bg-background">
46	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
47	    </div>
48	  );
49	}
50	
51	const queryClient = new QueryClient({
52	  defaultOptions: {
53	    queries: {
54	      staleTime: 1000 * 60 * 2,
55	      gcTime: 1000 * 60 * 10,
56	      retry: (failureCount, error) => {
57	        const msg = error instanceof Error ? error.message : "";
58	        if (msg.includes("401") || msg.includes("403")) return false;
59	        return failureCount < 2;
60	      },
61	      refetchOnWindowFocus: false,
62	    },
63	    mutations: { retry: 0 },
64	  },
65	});
66	
67	const App = () => (
68	  <ThemeProvider attribute="class" defaultTheme="light" enableSystem={false}>
69	    <QueryClientProvider client={queryClient}>
70	      <TooltipProvider>
71	        <Toaster />
72	        <Sonner />
73	      <BrowserRouter>
74	        <AuthProvider>
75	          <Routes>
76	            {/* Public routes */}
77	            <Route path="/" element={<Landing />} />
78	            <Route path="/login" element={<Login />} />
79	            <Route path="/signup" element={<Signup />} />
80	            <Route path="/auth/callback" element={<AuthCallback />} />
81	            <Route path="/forgot-password" element={<ForgotPassword />} />
82	            <Route path="/reset-password" element={<ResetPassword />} />
83	            <Route path="/pricing" element={<Pricing />} />
84	            <Route path="/privacy" element={<Privacy />} />
85	            <Route path="/terms" element={<Terms />} />
86	
87	            {/* Protected app routes */}
88	            <Route element={<ProtectedRoute />}>
89	              <Route element={<AppLayout />}>
90	                <Route path="/dashboard" element={<Dashboard />} />
91	                <Route path="/scan" element={<Scan />} />
92	                <Route path="/reports" element={<Reports />} />
93	                <Route path="/reports/:id" element={<AuditReport />} />
94	                <Route path="/integrations" element={<Integrations />} />
95	                <Route path="/settings" element={<SettingsPage />} />
96	              </Route>
97	
98	              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
99	              <Route element={<AdminRoute />}>
100	                <Route
101	                  path="/admin"
102	                  element={
103	                    <Suspense fallback={<AdminLoadingSpinner />}>
104	                      <AdminLayout />
105	                    </Suspense>
106	                  }
107	                >
108	                  <Route
109	                    index
110	                    element={
111	                      <Suspense fallback={<AdminLoadingSpinner />}>
112	                        <AdminDashboard />
113	                      </Suspense>
114	                    }
115	                  />
116	                  <Route
117	                    path="users"
118	                    element={
119	                      <Suspense fallback={<AdminLoadingSpinner />}>
120	                        <AdminUsers />
121	                      </Suspense>
122	                    }
123	                  />
124	                  <Route
125	                    path="users/:userId"
126	                    element={
127	                      <Suspense fallback={<AdminLoadingSpinner />}>
128	                        <AdminUserDetail />
129	                      </Suspense>
130	                    }
131	                  />
132	                  <Route
133	                    path="audit-log"
134	                    element={
135	                      <Suspense fallback={<AdminLoadingSpinner />}>
136	                        <AdminAuditLog />
137	                      </Suspense>
138	                    }
139	                  />
140	                  <Route
141	                    path="scans"
142	                    element={
143	                      <Suspense fallback={<AdminLoadingSpinner />}>
144	                        <AdminScans />
145	                      </Suspense>
146	                    }
147	                  />
148	                  <Route
149	                    path="billing"
150	                    element={
151	                      <Suspense fallback={<AdminLoadingSpinner />}>
152	                        <AdminBilling />
153	                      </Suspense>
154	                    }
155	                  />
156	                  <Route
157	                    path="system"
158	                    element={
159	                      <Suspense fallback={<AdminLoadingSpinner />}>
160	                        <AdminSystem />
161	                      </Suspense>
162	                    }
163	                  />
164	                  <Route
165	                    path="flags"
166	                    element={
167	                      <Suspense fallback={<AdminLoadingSpinner />}>
168	                        <AdminFeatureFlags />
169	                      </Suspense>
170	                    }
171	                  />
172	                  <Route
173	                    path="support"
174	                    element={
175	                      <Suspense fallback={<AdminLoadingSpinner />}>
176	                        <AdminSupport />
177	                      </Suspense>
178	                    }
179	                  />
180	                </Route>
181	              </Route>
182	            </Route>
183	
184	            <Route path="*" element={<NotFound />} />
185	          </Routes>
186	        </AuthProvider>
187	      </BrowserRouter>
188	      </TooltipProvider>
189	    </QueryClientProvider>
190	  </ThemeProvider>
191	);
192	
193	export default App;
194

