import {
  CreditCard,
  Zap,
  Gauge,
  Camera,
  Mail,
  Database,
  ExternalLink,
  Info,
  Lock,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

// ── Types ──────────────────────────────────────────────────────

type IntegrationStatus = "connected" | "server-side" | "missing";

interface IntegrationDef {
  id: string;
  name: string;
  category: string;
  description: string;
  status: IntegrationStatus;
  icon: React.ElementType;
  envVars: Array<{ name: string; resolved: boolean | null }>;
  externalUrl?: string;
  serverSideNote?: string;
}

// ── Status computation (VITE_ vars are visible; server vars are not) ──

const stripeStatus: IntegrationStatus = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY
  ? "connected"
  : "missing";

const supabaseStatus: IntegrationStatus =
  import.meta.env.VITE_SUPABASE_URL && import.meta.env.VITE_SUPABASE_ANON_KEY
    ? "connected"
    : "missing";

// ── Integration definitions ────────────────────────────────────

const INTEGRATIONS: IntegrationDef[] = [
  {
    id: "stripe",
    name: "Stripe",
    category: "Billing",
    description:
      "Processes subscription payments, manages plan upgrades, and handles invoicing for all ConvertScan tiers.",
    status: stripeStatus,
    icon: CreditCard,
    envVars: [
      {
        name: "VITE_STRIPE_PUBLISHABLE_KEY",
        resolved: Boolean(import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY),
      },
      {
        name: "STRIPE_SECRET_KEY",
        resolved: null,
      },
      {
        name: "STRIPE_WEBHOOK_SECRET",
        resolved: null,
      },
    ],
    externalUrl: "https://dashboard.stripe.com",
  },
  {
    id: "anthropic",
    name: "Anthropic Claude API",
    category: "AI Engine",
    description:
      "Powers Vision + Text analysis across all 7 CRO pillars, generating scored findings and AI rewrite suggestions.",
    status: "server-side",
    icon: Zap,
    envVars: [
      {
        name: "ANTHROPIC_API_KEY",
        resolved: null,
      },
    ],
    externalUrl: "https://console.anthropic.com",
    serverSideNote: "Model: claude-sonnet-4-20250514",
  },
  {
    id: "pagespeed",
    name: "Google PageSpeed",
    category: "Performance",
    description:
      "Provides Core Web Vitals, performance scores, and diagnostic data for the Page Performance CRO pillar.",
    status: "server-side",
    icon: Gauge,
    envVars: [
      {
        name: "PAGESPEED_API_KEY",
        resolved: null,
      },
    ],
    externalUrl: "https://console.cloud.google.com",
  },
  {
    id: "screenshot",
    name: "Screenshot Service",
    category: "Visual Analysis",
    description:
      "Captures full-page screenshots via Puppeteer on Railway, used as input for AI visual hierarchy analysis.",
    status: "server-side",
    icon: Camera,
    envVars: [
      {
        name: "SCREENSHOT_SERVICE_URL",
        resolved: null,
      },
      {
        name: "SCREENSHOT_SERVICE_API_KEY",
        resolved: null,
      },
    ],
  },
  {
    id: "resend",
    name: "Resend",
    category: "Email",
    description:
      "Delivers transactional emails including scan completion notifications, plan receipts, and onboarding sequences.",
    status: "server-side",
    icon: Mail,
    envVars: [
      {
        name: "RESEND_API_KEY",
        resolved: null,
      },
    ],
    externalUrl: "https://resend.com",
  },
  {
    id: "supabase",
    name: "Supabase",
    category: "Infrastructure",
    description:
      "Provides authentication, PostgreSQL database, row-level security, storage for screenshots, and Edge Function hosting.",
    status: supabaseStatus,
    icon: Database,
    envVars: [
      {
        name: "VITE_SUPABASE_URL",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_URL),
      },
      {
        name: "VITE_SUPABASE_ANON_KEY",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_ANON_KEY),
      },
      {
        name: "SUPABASE_SERVICE_ROLE_KEY",
        resolved: null,
      },
    ],
    externalUrl: "https://supabase.com/dashboard",
  },
];

// ── Style maps ─────────────────────────────────────────────────

const STATUS_BADGE: Record<
  IntegrationStatus,
  { label: string; className: string }
> = {
  connected: {
    label: "Connected",
    className: "bg-green-100 text-green-700 border-0",
  },
  "server-side": {
    label: "Server-side",
    className: "bg-amber-100 text-amber-700 border-0",
  },
  missing: {
    label: "Not configured",
    className: "bg-red-100 text-red-700 border-0",
  },
};

const CATEGORY_BADGE: Record<string, string> = {
  Billing: "bg-indigo-100 text-indigo-700 border-0",
  "AI Engine": "bg-purple-100 text-purple-700 border-0",
  Performance: "bg-orange-100 text-orange-700 border-0",
  "Visual Analysis": "bg-sky-100 text-sky-700 border-0",
  Email: "bg-pink-100 text-pink-700 border-0",
  Infrastructure: "bg-slate-100 text-slate-700 border-0",
};

// ── Sub-components ─────────────────────────────────────────────

function EnvVarRow({
  name,
  resolved,
}: {
  name: string;
  resolved: boolean | null;
}) {
  const isClientSide = resolved !== null;

  return (
    <div className="flex items-center justify-between gap-3 py-1">
      <code className="font-mono text-xs text-muted-foreground/80 truncate">
        {name}
      </code>
      {isClientSide ? (
        <Badge
          className={
            resolved
              ? "bg-green-100 text-green-700 border-0 text-2xs px-1.5 py-0 shrink-0"
              : "bg-red-100 text-red-700 border-0 text-2xs px-1.5 py-0 shrink-0"
          }
        >
          {resolved ? "Set" : "Missing"}
        </Badge>
      ) : (
        <div className="flex items-center gap-1 shrink-0">
          <Lock className="h-2.5 w-2.5 text-muted-foreground/40" />
          <span className="text-2xs text-muted-foreground/50">Secret</span>
        </div>
      )}
    </div>
  );
}

function IntegrationCard({ integration }: { integration: IntegrationDef }) {
  const { icon: Icon, status, category } = integration;
  const statusBadge = STATUS_BADGE[status];
  const categoryBadgeClass =
    CATEGORY_BADGE[category] ?? "bg-muted/50 text-foreground/70 border-0";

  const hasClientSideVars = integration.envVars.some((v) => v.resolved !== null);
  const allServerSide = integration.envVars.every((v) => v.resolved === null);

  return (
    <Card className="border-border/50 shadow-soft flex flex-col">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-3">
          {/* Icon + name */}
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-muted/60 shrink-0">
              <Icon className="h-4.5 w-4.5 text-foreground/70" />
            </div>
            <div>
              <CardTitle className="text-sm font-semibold leading-tight">
                {integration.name}
              </CardTitle>
              <Badge
                className={`mt-1 text-2xs px-1.5 py-0 ${categoryBadgeClass}`}
              >
                {category}
              </Badge>
            </div>
          </div>

          {/* Status badge */}
          <Badge className={`text-xs px-2 py-0.5 shrink-0 ${statusBadge.className}`}>
            {statusBadge.label}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="flex-1 flex flex-col gap-4">
        {/* Description */}
        <p className="text-xs text-muted-foreground leading-relaxed">
          {integration.description}
        </p>

        {/* Configuration section */}
        <div className="rounded-lg bg-muted/40 px-3 py-2.5 space-y-0.5">
          <p className="text-2xs font-medium uppercase tracking-wider text-muted-foreground/60 mb-2">
            Configuration
          </p>
          {integration.envVars.map((v) => (
            <EnvVarRow key={v.name} name={v.name} resolved={v.resolved} />
          ))}
          {(allServerSide || !hasClientSideVars) && (
            <p className="text-2xs text-muted-foreground/50 mt-2 pt-2 border-t border-border/40 leading-relaxed">
              Keys configured in Supabase Edge Function secrets
            </p>
          )}
          {integration.serverSideNote && (
            <p className="text-2xs text-muted-foreground/50 leading-relaxed">
              {integration.serverSideNote}
            </p>
          )}
        </div>

        {/* Spacer to push button to bottom */}
        <div className="flex-1" />

        {/* Open Dashboard button */}
        {integration.externalUrl ? (
          <Button
            variant="outline"
            size="sm"
            className="w-full border-border/60 text-xs"
            asChild
          >
            <a
              href={integration.externalUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
              Open Dashboard
            </a>
          </Button>
        ) : (
          <div className="flex items-center justify-center gap-1.5 py-1.5 rounded-md border border-dashed border-border/50">
            <Info className="h-3 w-3 text-muted-foreground/40" />
            <span className="text-2xs text-muted-foreground/50">
              No external dashboard
            </span>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// ── Summary chip ───────────────────────────────────────────────

function SummaryChip({
  label,
  count,
  colorClass,
}: {
  label: string;
  count: number;
  colorClass: string;
}) {
  return (
    <div
      className={`flex items-center gap-2 rounded-lg border px-3 py-2.5 ${colorClass}`}
    >
      <span className="text-xl font-semibold tabular-nums">{count}</span>
      <span className="text-xs font-medium leading-tight">{label}</span>
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminIntegrations() {
  const connectedCount = INTEGRATIONS.filter(
    (i) => i.status === "connected"
  ).length;
  const serverSideCount = INTEGRATIONS.filter(
    (i) => i.status === "server-side"
  ).length;
  const missingCount = INTEGRATIONS.filter(
    (i) => i.status === "missing"
  ).length;

  return (
    <div className="space-y-8">
      <PageHeader
        title="Platform Integrations"
        description="Manage and monitor all external services connected to ConvertScan."
      />

      {/* Summary chips */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <SummaryChip
          label="Total integrations"
          count={INTEGRATIONS.length}
          colorClass="border-border/50 bg-muted/30 text-foreground"
        />
        <SummaryChip
          label="Connected"
          count={connectedCount}
          colorClass="border-green-200 bg-green-50 text-green-800"
        />
        <SummaryChip
          label="Server-side"
          count={serverSideCount}
          colorClass="border-amber-200 bg-amber-50 text-amber-800"
        />
        <SummaryChip
          label="Not configured"
          count={missingCount}
          colorClass={
            missingCount > 0
              ? "border-red-200 bg-red-50 text-red-800"
              : "border-border/50 bg-muted/30 text-muted-foreground"
          }
        />
      </div>

      {/* Info banner */}
      <div
        role="note"
        className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3.5"
      >
        <Info className="h-4 w-4 text-amber-500 mt-0.5 shrink-0" />
        <div>
          <p className="text-sm font-medium text-amber-800">
            Server-side secrets cannot be viewed here
          </p>
          <p className="text-xs text-amber-700 mt-0.5 leading-relaxed">
            Service keys marked as{" "}
            <span className="font-medium">Server-side</span> are stored as
            Supabase Edge Function secrets and are never exposed to the browser.
            Manage them in the{" "}
            <a
              href="https://supabase.com/dashboard"
              target="_blank"
              rel="noopener noreferrer"
              className="underline underline-offset-2 hover:text-amber-900 transition-colors"
            >
              Supabase Dashboard
            </a>{" "}
            under Edge Functions → Secrets.
          </p>
        </div>
      </div>

      {/* Integration cards — 2-col grid */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
        {INTEGRATIONS.map((integration) => (
          <IntegrationCard key={integration.id} integration={integration} />
        ))}
      </div>
    </div>
  );
}

